#!/usr/bin/env python3
"""Authored Korean history expansion; extract exact evidence from imported notes.
Run from any directory. This writes only extended-inputs/hanguksa.json.
Seeds are authored questions, not inferred KICE answers or official grading keys.
"""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
NOTES={n['id']:n for n in json.loads((ROOT/'public/data/subjects/hanguksa/notes.json').read_text())}
Q=[]
def page(p): return f'hanguksa-{"gichul" if str(p).startswith("g") else "textbook"}-page-{str(p).lstrip("g")}'
def ev(p, needle, before=2, after=2):
    n=NOTES[page(p)]['text']; lines=n.splitlines(keepends=True)
    ix=next((i for i,s in enumerate(lines) if needle in s),None)
    if ix is None: ix=next((i for i,s in enumerate(lines) if ''.join(needle.split()) in ''.join(s.split())),None)
    if ix is None: raise ValueError((p,needle))
    quote=''.join(lines[max(0,ix-before):ix+after+1]).strip()
    assert quote in n
    return {'page':page(p),'quote':quote}
def add(t, slug, prompt, answer, explain, refs, **kw):
    q=dict(id='hanguksa-ext-'+slug,type=t,skill=kw.pop('skill','fact'),prompt=prompt,answer=answer,explain=explain,evidence=[ev(*r) for r in refs],**kw)
    Q.append(q)
def shorts(data):
    for row in data.strip().splitlines():
        slug,p,needle,answer,prompt,explain,*aliases=row.split('|')
        add('short',slug,prompt,answer,explain,[(p,needle)],**({'acceptedAnswers':aliases[0].split('/')} if aliases else {}))
