def refs(spec):
    out=[]
    for item in spec.split(';;'):
        a=item.split('@'); out.append((a[0],a[1],*(int(x) for x in a[2:])))
    return out

def mcs(data):
    for row in data.strip().splitlines():
        slug,rs,skill,prompt,*options=row.split('|')
        assert len(options)==4,(slug,options)
        pairs=[o.split('~') for o in options]
        # Rotate authored correct option to remove position cues.
        rotation=len([q for q in Q if q['type']=='mc'])%4
        pairs=pairs[-rotation:]+pairs[:-rotation] if rotation else pairs
        add('mc',slug,prompt,rotation,options[0].split('~')[1],refs(rs),skill=skill,choices=[p[0] for p in pairs],choiceExplanations=[p[1] for p in pairs])

