if __name__=='__main__':
    from collections import Counter
    target=Path(__file__).resolve().parent/'extended-inputs/hanguksa.json'
    counts=Counter(q['type'] for q in Q)
    assert counts=={'short':100,'mc':120,'blank':50,'essay':30},counts
    target.parent.mkdir(parents=True,exist_ok=True)
    target.write_text(json.dumps({'schemaVersion':1,'subject':'hanguksa','questions':Q},ensure_ascii=False,indent=2)+'\n')
    print(f'Wrote {len(Q)} authored questions: {dict(counts)}')
